# frozen_string_literal: true

module IncidentIoGenerator
  # Renders the templates and writes the generated files.
  class Writer
    TEMPLATES = File.expand_path("../templates", __dir__)
    HEADER = <<~RUBY.chomp
      # This file is generated by `rake generate` from openapi/openapi.json.
      # Do not edit it by hand.
    RUBY
    # Generated paths under lib/incident_io. Removed before each run so files
    # for deleted schemas or tags don't linger.
    GENERATED = %w[models models.rb resources resources.rb].freeze
    # Keep method signatures on one line up to this width.
    MAX_LINE = 110

    attr_reader :api

    def initialize(api, out_dir)
      @api = api
      @out_dir = out_dir
    end

    # Writes every file and returns their paths relative to out_dir.
    def write
      GENERATED.each { |path| FileUtils.rm_rf(File.join(@out_dir, path)) }

      files = {}
      files["models.rb"] = render("models_index")
      api.models.each { |model| files["models/#{model.file_name}.rb"] = render("model", model:) }
      files["resources.rb"] = render("resources_index")
      api.resources.each { |resource| files["#{resource.file_path}.rb"] = render("resource", resource:) }

      files.each do |path, source|
        full = File.join(@out_dir, path)
        FileUtils.mkdir_p(File.dirname(full))
        File.write(full, source)
      end
      files.keys
    end

    # Turns free text into Ruby comment lines at the given indent. Returns
    # "" for blank text.
    def comment(text, indent)
      return "" if text.nil? || text.strip.empty?

      pad = " " * indent
      text.strip.lines.map { |line| line.rstrip.empty? ? "#{pad}#\n" : "#{pad}# #{line.rstrip}\n" }.join
    end

    # YARD docs for a generated method.
    def method_docs(op, indent)
      lines = []
      lines << (op.description || op.summary).to_s.strip
      lines << ""
      endpoint = "Endpoint: `#{op.http_method.upcase} #{op.path}`."
      endpoint += " Scopes: #{op.scopes.join(", ")}." if op.scopes.any?
      lines << endpoint
      lines << "Does not use your API key; pass the alert source token instead." if op.no_auth
      lines << ""
      if op.deprecated
        lines << (op.replacement ? "@deprecated Use `#{op.replacement}` instead." : "@deprecated incident.io has deprecated this endpoint.")
      end
      (op.path_params + op.keyword_params).each do |p|
        detail = sentence(p.description)
        detail = [detail, "Generated when not given."].compact.join(" ") if p.default
        type = Types.yard_type(p.schema, accepts_hash: true)
        lines << "@param #{p.name} [#{type}]#{" #{detail}" if detail}"
      end
      lines << "@param request_options [Hash] Per-call options, see IncidentIo::Client#request."
      lines << "@return [#{op.result.yard}]"
      comment(lines.join("\n"), indent)
    end

    # The parameter list of a generated method.
    def signature(op, indent)
      args = op.path_params.map(&:name)
      op.keyword_params.each do |p|
        args << if p.required then "#{p.name}:"
                elsif p.default then "#{p.name}: #{p.default}"
                else "#{p.name}: nil"
                end
      end
      args << "request_options: {}"

      one_line = "def #{op.method_name}(#{args.join(", ")})"
      return one_line if indent + one_line.length <= MAX_LINE

      pad = " " * (indent + 2)
      "def #{op.method_name}(\n#{args.map { |a| "#{pad}#{a}" }.join(",\n")}\n#{" " * indent})"
    end

    # The body of a generated method: one request or paginate call.
    def call(op, indent)
      pad = " " * (indent + 2)
      args = []

      if op.result.kind == :paginated
        args << path_expression(op)
        args << "items_key: #{op.result.items_key.inspect}"
        args << "query: #{hash_expression(op.query_params, indent + 2)}" if op.query_params.any?
        args << "model: #{op.result.model}" if op.result.model
        args << "request_options:"
        return "#{" " * indent}paginate(\n#{args.map { |a| "#{pad}#{a}" }.join(",\n")}\n#{" " * indent})"
      end

      args << ":#{op.http_method}"
      args << path_expression(op)
      args << "query: #{hash_expression(op.query_params, indent + 2)}" if op.query_params.any?
      args << "body: #{hash_expression(op.body_params, indent + 2)}#{".compact" if op.body_params.any?}" if op.body
      args << "idempotent: true" if op.idempotent
      args << "unwrap: #{op.result.unwrap.inspect}" if op.result.unwrap
      args << "model: #{op.result.model}" if op.result.model
      args << "request_options:"
      "#{" " * indent}request(\n#{args.map { |a| "#{pad}#{a}" }.join(",\n")}\n#{" " * indent})"
    end

    # Ruby source of a hash literal, a key per line when it doesn't fit.
    def hash_expression(params, indent)
      return "{}" if params.empty?

      entries = params.map { |p| "#{p.name}:" }
      one_line = "{ #{entries.join(", ")} }"
      return one_line if indent + one_line.length + 10 <= MAX_LINE

      pad = " " * (indent + 2)
      "{\n#{entries.map { |e| "#{pad}#{e}" }.join(",\n")}\n#{" " * indent}}"
    end

    def path_expression(op)
      return op.path.inspect if op.path_params.empty?

      template = op.path.gsub("%", "%%").gsub(/\{\w+\}/, "%s")
      "path(#{template.inspect}, #{op.path_params.map(&:name).join(", ")})"
    end

    # A hash key in `Model.define(...)`.
    def model_key(name)
      Naming.safe_identifier?(name) || Naming::RUBY_KEYWORDS.include?(name) ? "#{name}:" : "#{name.inspect}:"
    end

    # Ends text with a full stop unless it already ends a sentence.
    def sentence(text)
      return nil if text.nil?

      text.match?(/[.!?)]\z/) ? text : "#{text}."
    end

    # First sentence of a description, for short attribute docs.
    def first_sentence(text)
      return nil if text.nil?

      text[/\A.*?[.!?](?=\s|\z)/] || text
    end

    private

    def render(name, **locals)
      @templates ||= {}
      template = @templates[name] ||= ERB.new(File.read(File.join(TEMPLATES, "#{name}.rb.erb")), trim_mode: "-")
      template.result_with_hash(helpers: self, header: HEADER, api:, **locals)
    end
  end
end
